package com.projexa.coaching.academics.service;
import com.projexa.coaching.common.exceptions.ApiException; import com.projexa.coaching.common.tenant.TenantContextHolder; import com.projexa.coaching.academics.entity.Batch; import com.projexa.coaching.academics.repository.BatchRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class BatchService { private final BatchRepository repo; public BatchService(BatchRepository repo){this.repo=repo;} public List<Batch> list(){return repo.findAllByTenantId(TenantContextHolder.getRequired());} public Batch get(UUID id){return repo.findByIdAndTenantId(id,TenantContextHolder.getRequired()).orElseThrow(()->new ApiException("NOT_FOUND","Resource not found"));} public Batch create(Batch item){item.setTenantId(TenantContextHolder.getRequired()); return repo.save(item);} public Batch update(UUID id,Batch item){Batch current=get(id); copy(item,current); return repo.save(current);} public void delete(UUID id){repo.delete(get(id));} private void copy(Batch s,Batch t){t.setAcademicYearId(s.getAcademicYearId());t.setClassId(s.getClassId());t.setStreamId(s.getStreamId());t.setName(s.getName());t.setCode(s.getCode());t.setCapacity(s.getCapacity());t.setStatus(s.getStatus());}}